// Type declarations for static asset and style imports used by the ui-desktop package
// Ensures TypeScript and tooling can resolve imports like `import './App.css'`.
declare module "*.css";
declare module "*.scss";
declare module "*.module.css";
declare module "*.module.scss";
declare module "*.png";
declare module "*.jpg";
declare module "*.jpeg";
declare module "*.gif";
declare module "*.svg";
declare module "*.webp";
declare module "*.json";
